mapper.select:
SELECT o.id AS id, o.option_type AS optionType, o.event_code AS eventCode, o.event_label AS eventLabel, o.org_id AS orgId, o.category AS category, o.icon AS icon, o.status AS status, ( SELECT COUNT(1) FROM gift_event_info_t e WHERE e.is_delete = 0
AND e.org_id = #{orgId}
AND ( (o.option_type = 'SYSTEM' AND (e.event_type = o.event_code OR e.event_type = o.event_label)) OR (o.option_type = 'CUSTOM' AND e.event_type = o.event_label) ) ) AS useCount, o.default_amount AS defaultAmount, o.sort_order AS sortOrder FROM gift_event_type_option_t o WHERE o.is_delete = 0 AND ( (o.option_type = 'SYSTEM' AND o.user_id = 0) OR (o.option_type = 'CUSTOM' AND o.org_id = #{orgId}) ) ORDER BY CASE o.option_type WHEN 'SYSTEM' THEN 0 ELSE 1 END, o.sort_order ASC, o.last_used_time DESC, o.event_label ASC
